package io.github.ugaikit.gemini4kt

import kotlinx.serialization.Serializable
import kotlin.js.ExperimentalJsExport
import kotlin.js.JsExport

/**
 * Represents the code execution result.
 *
 * @property outcome The outcome.
 * @property output The output.
 * @property image An image generated by the executed code, when available.
 */
@OptIn(ExperimentalJsExport::class)
@JsExport
@Serializable
data class CodeExecutionResult(
    val outcome: String,
    val output: String? = null,
    val image: InlineData? = null,
)

/**
 * Represents the code execution result builder.
 */
class CodeExecutionResultBuilder {
    /**
     * Holds the outcome.
     */
    private var outcome: String = ""

    /**
     * Holds the output.
     */
    private var output: String? = null

    /**
     * Holds the image.
     */
    private var image: InlineData? = null

    /**
     * Handles outcome.
     *
     * @param init The init.
     */
    fun outcome(init: () -> String) = apply { outcome = init() }

    /**
     * Handles output.
     *
     * @param init The init.
     */
    fun output(init: () -> String?) = apply { output = init() }

    /**
     * Handles image.
     *
     * @param init The init.
     */
    fun image(init: InlineDataBuilder.() -> Unit) = apply { image = InlineDataBuilder().apply(init).build() }

    /**
     * Handles build.
     */
    fun build() =
        CodeExecutionResult(
            outcome = outcome,
            output = output,
            image = image,
        )
}

/**
 * Handles code execution result.
 *
 * @param init The init.
 */
fun codeExecutionResult(init: CodeExecutionResultBuilder.() -> Unit): CodeExecutionResult =
    CodeExecutionResultBuilder()
        .apply(init)
        .build()
